// core/common.js — 平台无关公共件: 日志 + 参数解析 + 存储辅助
// 各平台沙箱均以单脚本执行, 本文件为拼装片段, 勿加 import/export。

const Log = {
  level: 3, // 0 off, 1 error, 2 warn, 3 info, 4 debug
  groups: [],
  set logLevel(v) {
    const map = { off: 0, error: 1, warn: 2, warning: 2, info: 3, debug: 4, all: 5 };
    this.level = typeof v === "number" ? v : (map[String(v).toLowerCase()] ?? 2);
  },
  print(...args) {
    if (this.level === 0) return;
    let lines = args.flatMap((a) => {
      if (typeof a === "object") return [JSON.stringify(a)];
      if (typeof a === "bigint" || typeof a === "number" || typeof a === "boolean") return [a.toString()];
      return String(a).split(/\r?\n/);
    });
    for (const g of this.groups) {
      lines = lines.map((l) => `  ${l}`);
      lines.unshift(` ${g}:`);
    }
    console.log(["", ...lines].join("\n"));
  },
  info(...a) { if (this.level >= 3) this.print(...a.map((x) => ` ${x}`)); },
  warn(...a) { if (this.level >= 2) this.print(...a.map((x) => ` ${x}`)); },
  error(...a) { if (this.level >= 1) this.print(...a.map((x) => ` ${x}`)); },
  debug(...a) { if (this.level >= 4) this.print(...a.map((x) => ` ${x}`)); },
  group(name) { this.groups.unshift(name); },
  groupEnd() { this.groups.shift(); },
};

// key=value&... → 对象 (宽容解析); 键值均解码, "+" 视为空格, 首个键胜出
function parseParams(input) {
  const out = {};
  if (typeof input !== "string") return out;
  for (const pair of input.replace(/^\?/, "").split("&")) {
    if (!pair) continue;
    const i = pair.indexOf("=");
    const rawKey = i < 0 ? pair : pair.slice(0, i);
    const rawValue = i < 0 ? "" : pair.slice(i + 1);
    try {
      const key = decodeURIComponent(rawKey.replace(/\+/g, " "));
      if (!(key in out)) out[key] = decodeURIComponent(rawValue.replace(/\+/g, " "));
    } catch {}
  }
  return out;
}

// 存储辅助: 各平台存储只收字符串, 这里统一 JSON 编解码与默认值
function storeGetParsed(storeGet, key, fallback = null) {
  let v = storeGet(key);
  try { v = JSON.parse(v); } catch {}
  return v ?? fallback;
}

function storeSetString(storeSet, key, value) {
  const s = typeof value === "object" ? JSON.stringify(value) : String(value);
  return storeSet(key, s);
}

// core/gcj.js — GCJ-02 ↔ WGS84 (设备端换算)
// 中国大陆苹果地图/高德坐标为 GCJ-02 偏移坐标; 迭代反算收敛到亚米级。
const GCJ_A = 6378245.0;
const GCJ_EE = 0.00669342162296594323;

const gcjOutOfChina = (lon, lat) => lon < 72.004 || lon > 137.8347 || lat < 0.8293 || lat > 55.8271;

function gcjDeltaLat(x, y) {
  let r = -100.0 + 2.0 * x + 3.0 * y + 0.2 * y * y + 0.1 * x * y + 0.2 * Math.sqrt(Math.abs(x));
  r += ((20.0 * Math.sin(6.0 * x * Math.PI) + 20.0 * Math.sin(2.0 * x * Math.PI)) * 2.0) / 3.0;
  r += ((20.0 * Math.sin(y * Math.PI) + 40.0 * Math.sin((y / 3.0) * Math.PI)) * 2.0) / 3.0;
  r += ((160.0 * Math.sin((y / 12.0) * Math.PI) + 320 * Math.sin((y * Math.PI) / 30.0)) * 2.0) / 3.0;
  return r;
}

function gcjDeltaLon(x, y) {
  let r = 300.0 + x + 2.0 * y + 0.1 * x * x + 0.1 * x * y + 0.1 * Math.sqrt(Math.abs(x));
  r += ((20.0 * Math.sin(6.0 * x * Math.PI) + 20.0 * Math.sin(2.0 * x * Math.PI)) * 2.0) / 3.0;
  r += ((20.0 * Math.sin(x * Math.PI) + 40.0 * Math.sin((x / 3.0) * Math.PI)) * 2.0) / 3.0;
  r += ((150.0 * Math.sin((x / 12.0) * Math.PI) + 300.0 * Math.sin((x / 30.0) * Math.PI)) * 2.0) / 3.0;
  return r;
}

// WGS84 -> GCJ-02 (正向偏移)
function wgs84ToGcj02(lat, lon) {
  if (gcjOutOfChina(lon, lat)) return { lat, lon };
  let dLat = gcjDeltaLat(lon - 105.0, lat - 35.0);
  let dLon = gcjDeltaLon(lon - 105.0, lat - 35.0);
  const radLat = (lat / 180.0) * Math.PI;
  let magic = Math.sin(radLat);
  magic = 1 - GCJ_EE * magic * magic;
  const sqrtMagic = Math.sqrt(magic);
  dLat = (dLat * 180.0) / (((GCJ_A * (1 - GCJ_EE)) / (magic * sqrtMagic)) * Math.PI);
  dLon = (dLon * 180.0) / ((GCJ_A / sqrtMagic) * Math.cos(radLat) * Math.PI);
  return { lat: lat + dLat, lon: lon + dLon };
}

// GCJ-02 -> WGS84 (不动点迭代反算, <0.1m)
function gcj02ToWgs84(lat, lon) {
  if (gcjOutOfChina(lon, lat)) return { lat, lon };
  let wgsLat = lat;
  let wgsLon = lon;
  for (let i = 0; i < 6; i++) {
    const g = wgs84ToGcj02(wgsLat, wgsLon);
    const errLat = g.lat - lat;
    const errLon = g.lon - lon;
    if (Math.abs(errLat) < 1e-9 && Math.abs(errLon) < 1e-9) break;
    wgsLat -= errLat;
    wgsLon -= errLon;
  }
  return { lat: wgsLat, lon: wgsLon };
}

// core/settings.js — /wloc-settings/save 参数处理 (平台无关)
// 输入 query 对象 + 存储读写函数 (经参数注入), 输出结果对象。

const KEY = "wloc_settings";

function processSettings(query, storeGet, storeSet) {
  const action = query.action || "save";
  let result;
  if (action === "query") {
    // 查询已存坐标
    try {
      const saved = storeGetParsed(storeGet, KEY);
      if (saved && typeof saved === "object" && saved.longitude && saved.latitude) {
        result = {
          success: true,
          longitude: saved.longitude,
          latitude: saved.latitude,
          accuracy: saved.accuracy || 25,
          updatedAt: saved.updatedAt || null,
        };
      } else {
        result = { success: false, error: "无已保存的坐标" };
      }
    } catch (e) {
      result = { success: false, error: e.message || "读取失败" };
    }
  } else if (action === "clear") {
    // 清除坐标 → wloc 进入透传模式 → 恢复真实定位
    try {
      storeSetString(storeSet, KEY, null);
      result = { success: true };
      Log.info("[wloc-settings] 已清除坐标数据");
    } catch (e) {
      result = { success: false, error: e.message || "清除失败" };
      Log.error(`[wloc-settings] 清除失败: ${e.message}`);
    }
  } else {
    // 保存坐标 (cs=gcj 时先设备端转 WGS84)
    const lonRaw = query.lon || query.longitude;
    const latRaw = query.lat || query.latitude;
    let lon = parseFloat(lonRaw);
    let lat = parseFloat(latRaw);
    const acc = parseInt(query.acc || query.accuracy || "25", 10);
    if (!Number.isFinite(lon) || lon < -180 || lon > 180) {
      result = { success: false, error: "lon 超出范围 (-180..180)" };
    } else if (!Number.isFinite(lat) || lat < -90 || lat > 90) {
      result = { success: false, error: "lat 超出范围 (-90..90)" };
    } else if (!Number.isFinite(acc) || acc < 0) {
      result = { success: false, error: "acc 非法 (需 ≥0)" };
    } else {
      if ((query.cs || "").toLowerCase() === "gcj") {
        const w = gcj02ToWgs84(lat, lon);
        lon = w.lon;
        lat = w.lat;
      }
      const record = {
        longitude: lon,
        latitude: lat,
        accuracy: acc,
        updatedAt: new Date(Date.now() + 288e5).toISOString().replace("Z", "+08:00"), // 北京时间
      };
      try {
        if (storeSetString(storeSet, KEY, record)) {
          result = { success: true, longitude: lon, latitude: lat, accuracy: acc };
          Log.info(`[wloc-settings] 已保存: ${lon}, ${lat}`);
        } else {
          result = { success: false, error: "storeSet 返回 false" };
          Log.error("[wloc-settings] storeSet 返回 false");
        }
      } catch (e) {
        result = { success: false, error: e.message || "写入失败" };
        Log.error(`[wloc-settings] ${e.message}`);
      }
    }
  }
  return result;
}

// platform/qx.js — Quantumult X 胶水
// 只定义 Platform 对象, 不执行任何顶层逻辑。核心经注入的存储/参数函数使用本层。
// QX API: $prefs.valueForKey/setValueForKey, $response.bodyBytes(内核已解压 gzip),
//         脚本 URL # 参数经 $environment.sourcePath, 输出 $done({bodyBytes})。

const Platform = {
  // 存储: 只收字符串
  storeGet(key) { return $prefs.valueForKey(key); },
  storeSet(key, value) { return $prefs.setValueForKey(value, key); },

  // 模块参数: 脚本 URL 的 # 之后 (# 内容不发送到服务器)
  argument() {
    try {
      const sp = globalThis.$environment?.sourcePath || "";
      const i = sp.indexOf("#");
      return i >= 0 ? sp.slice(i + 1) : "";
    } catch {
      return "";
    }
  },

  requestUrl() { return typeof $request !== "undefined" ? $request.url || "" : ""; },
  requestMethod() { return typeof $request !== "undefined" ? $request.method || "" : ""; },

  // 响应体: QX 内核已自动解压 gzip, 直接给 ArrayBuffer
  responseBodyBytes() { return $response.bodyBytes; },

  // wloc 输出: 官方示例要求用 buffer.slice 裁掉可能的偏移
  wlocDone(out) {
    const b = Uint8Array.from(out);
    return { bodyBytes: b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength) };
  },

  // settings 输出: status 为完整状态行
  jsonDone(result) {
    return {
      status: "HTTP/1.1 200 OK",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(result),
    };
  },

  done(r) { $done(r); },
};

// entry/settings.js — wloc-settings 入口 (QX/Surge 通用, 平台差异全在 Platform)
// QX 在响应阶段执行 (覆盖 Apple 404); Surge 在请求阶段执行 (直接合成响应, 不出设备)。
// 两种场景都从 $request.url 取参数, 输出由 Platform.jsonDone 定型。

const url = Platform.requestUrl();
const query = parseParams(url.split("?")[1] || "");
const result = processSettings(query, Platform.storeGet, Platform.storeSet);
Platform.done(Platform.jsonDone(result));
